"""Persist bounded manual review evidence without exposing notes in aggregate receipts."""
import json,gzip,re,hashlib
from pathlib import Path
R=Path(__file__).resolve().parent;ev=[]
known={('8d827103',5):'SB with',('8d827103',10):'SB with',('8d827103',20):'from SB',('8d827103',25):'SB with',('5e4af064',20):'in BB'}
for s in map(json.loads,gzip.open(R/'raw/parent5-visible-spans.jsonl.gz','rt')):
 p=json.loads(s['input']);u=[x['content']for x in p if x.get('role')=='user'];last=u[-1];m=re.match(r'^## Hand (\d+) is over',last)
 if not m:continue
 n=int(m[1]);needle=known.get((s['trace_id'][:8],n))
 if not needle:continue
 calls=[x for x in json.loads(s['output'])if x.get('type')=='function_call'];note=json.loads(calls[0]['arguments'])['contents'];decision=next(x for x in u if x.startswith(f'## Hand {n} of'));seatline=re.search(r'^Your seat:.*$',decision,re.M)[0];claim=next(x for x in note.splitlines()if needle in x);nameline=next(x for x in decision.splitlines()if '(you)'in x);ev.append({'trace_id':s['trace_id'],'span_id':s['span_id'],'hand':n,'note_claim_exact':claim,'original_decision_seat_exact':seatline,'player_identity_exact':nameline,'temporal_scope':'Current hand summary, not copied prior SP header','classification':'definite current blind-position contradiction; source player name is seatN, not SB/BB','source_input_sha256':hashlib.sha256(s['input'].encode()).hexdigest(),'source_output_sha256':hashlib.sha256(s['output'].encode()).hexdigest()})
(R/'raw/position-disambiguation-evidence.json').write_text(json.dumps(ev,indent=2)+'\n');aggregate=[{k:v for k,v in e.items()if k not in['note_claim_exact','original_decision_seat_exact','player_identity_exact']}for e in ev]
out={'scope':'Eightinitial parent5notes h5/h10/h20/h25 on2games. Bounded manual review, not full prose factuality or memory quality.','notes_reviewed':8,'all_explicit_current_stack_values_match_cleanup_input':8,'complete_six_seat_stack_tables':6,'tables_omitting_busted_zero_stack':2,'explicit_current_board_sequences_verified':5,'other_current_hands_end_preflop_no_board_claim':3,'own_hole_card_claims_reviewed':6,'own_hole_card_suit_contradictions':1,'definite_current_blind_position_errors':len(ev),'position_evidence_aggregate':aggregate,'unsupported_current_street_claims':1,'ambiguous_temporal_wording_not_counted_as_definite':1,'manual_verified_useful_prior_fact':{'notes_with_verified_prior_fact':1,'source_hand':24,'note_hand':25,'kind':'Previously publicly shown opponent cards exactly retained; original earlier cleanup USER is evidence, not scratchpad text.'},'current_public_card_category_error':1,'prior_memory':'Strict parser finds no fully verified blocks; manual one prior showdown-card fact verified. Other free-prose tendencies remain unknown.','no_raw_private_note_quotes_in_this_aggregate':True,'no_hidden_engine_truth_used':True}
(R/'initial-manual-audit.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({k:v for k,v in out.items()if k!='position_evidence_aggregate'},indent=2))
